// Reads a tuning.mvp authoring file: the record, or every finding about it (DAT-024).
[[nodiscard]] inline Neuron::RecordResult<TuningMvp> ReadTuningMvp(const Neuron::JsonDocument& _document)
{
  Neuron::RecordReader reader(_document.file);
  TuningMvp record;
  ReadFields(reader, reader.Record(_document.root, TUNING_MVP_SCHEMA_ID, TUNING_MVP_VERSION), record);
  if (reader.Failed())
  {
    return std::unexpected(reader.TakeDiagnostics());
  }
  return record;
}

